code:
//! `bsc imagine` — the producer. Turns what the ear heard into pictures.
//!
//! ## The renderer is DISCOVERED, never vendored
//!
//! The same pattern `bsc ear` uses for whisper (`$BSC_WHISPER_BIN`): the image model runs in a
//! process this crate does not own, and its address is `$BSC_SD_URL` (default `127.0.0.1:7860`).
//! Capability-probed rather than configured — the renderer either answers or it does not, and an
//! absent one reads as **absent**, never as an empty feed. That distinction is the whole reason
//! [`FeedState`] has four arms.
//!
//! ## The scene stage is OFF the clock, and optional
//!
//! Inferring "who is here, where, doing what" is a language model's job and measures ~509 ms —
//! twice the 250 ms budget on its own. So it never sits in front of the renderer. When
//! `$BSC_IMAGINE_LLM` names one it is consulted, and when it does not, the transcript is drawn
//! directly. Drawing straight from what was heard is a FASTER path, not a degraded one, which is
//! why [`Entry::scene`] is an `Option` rather than a string with a placeholder in it.

use bsc_cli_util::{args, CmdDoc};
use base64::Engine as _;
use crate::{store, worth_imagining, Budget, Cue, Entry, Scene, Skip, Tier};
use std::path::{Path, PathBuf};

pub const TAGLINE: &str = "what the ear hears, as pictures — one thought per entry";

pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "once",
        summary: "draw ONE thought from text you supply",
        usage: "\
bsc imagine once <text> [--dir <feed>] [--json|--pretty]

Draws one entry and appends it to the feed, exactly as `watch` would. This is the verb
for checking that a renderer actually answers before leaving anything running.

THE RENDERER IS DISCOVERED, NEVER VENDORED — $BSC_SD_URL, defaulting to 127.0.0.1:7860,
the same pattern `bsc ear` uses for whisper. An absent renderer is reported as ABSENT
and recorded as a fault on the feed, so the widget says nobody is drawing rather than
showing an empty room.",
    },
    CmdDoc {
        name: "watch",
        summary: "follow the ear's transcripts and draw each new one",
        usage: "\
bsc imagine watch [--ear <dir>] [--dir <feed>] [--once]

Follows the SAME transcript log the ear writes, so there is one source of truth for what
was heard. Every new line becomes a thought, unless it is blank, one of ASR's answers to
silence, or the same thing already drawn.

IT NEVER BLOCKS THE EAR. This is a separate process reading an append-only file; a slow
or dead renderer can only make pictures arrive late, never make capture stop.

--once processes what is already there and exits, which is what a test wants.",
    },
    CmdDoc {
        name: "status",
        summary: "the feed, and whether a renderer actually answers",
        usage: "\
bsc imagine status [--dir <feed>] [--json|--pretty]

Reports the feed's state — absent, empty, ready or failing — and PROBES the renderer
rather than reporting whatever was configured. A configured address that answers nothing
is the failure this distinguishes.",
    },
    CmdDoc {
        name: "sweep",
        summary: "enforce the bound now — trim the log and delete the evicted images",
        usage: "\
bsc imagine sweep [--dir <feed>] [--json|--pretty]

The bound is enforced after every draw; this runs it on demand. It deletes the IMAGES of
evicted entries, not merely their log lines — pictures of what was said in the room are
the thing the window actually promises to remove.",
    },
];

/// Where the renderer is, unless told otherwise.
pub const DEFAULT_SD_URL: &str = "http://127.0.0.1:7860";

/// How often `watch` re-reads the transcript log. Well under the rate speech arrives, and cheap:
/// the log is a few hundred bytes a line.
pub const WATCH_POLL_MS: u64 = 500;

/// The renderer's address.
pub fn sd_url() -> String {
    std::env::var("BSC_SD_URL").unwrap_or_else(|_| DEFAULT_SD_URL.to_string())
}

/// The scene model's address, when one is configured. `None` is a real answer: the producer draws
/// straight from the transcript, faster.
pub fn llm_url() -> Option<String> {
    std::env::var("BSC_IMAGINE_LLM").ok().filter(|s| !s.trim().is_empty())
}

/// The scene model's name.
pub fn llm_model() -> String {
    std::env::var("BSC_IMAGINE_MODEL").unwrap_or_else(|_| "qwen3.5:9b".to_string())
}

/// Mint an entry id from a timestamp and a counter. Alphanumeric and dashes only, because the app
/// turns it into a filename and validates it against exactly that set.
pub fn mint_id(at_unix_ms: i64, n: u64) -> String {
    format!("{at_unix_ms}-{n:03}")
}

/// A stable seed for a piece of text.
///
/// THE SEED IS THE SCENE AND THE PROMPT IS THE THOUGHT. Deriving the seed from something stable —
/// here the speaker's language tag, later their voiceprint — is what makes consecutive images feel
/// like one continuous world rather than a slideshow of cuts. MEASURED: a fixed seed across an
/// evolving prompt holds consecutive-frame SSIM at 0.957 against 0.450 for a fresh seed each time.
pub fn seed_for(key: &str) -> u32 {
    // FNV-1a, so the same key gives the same world on every machine and every run.
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for b in key.as_bytes() {
        h ^= *b as u64;
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    (h & 0x7fff_ffff) as u32
}

/// Ask the renderer to draw, and return the PNG bytes.
fn render_png(url: &str, prompt: &str, tier: Tier, seed: u32) -> Result<Vec<u8>, String> {
    let r = tier.render();
    let body = serde_json::json!({
        "prompt": prompt,
        "width": r.width,
        "height": r.height,
        "seed": seed,
        "sample_params": {
            "sample_steps": r.steps,
            "sample_method": "euler_a",
            // Turbo models are distilled to run without classifier-free guidance; anything above
            // 1.0 doubles the work per step for worse output.
            "guidance": { "txt_cfg": 1.0 }
        }
    });
    let client = reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(120))
        .build()
        .map_err(|e| format!("cannot build an http client: {e}"))?;
    let job: serde_json::Value = client
        .post(format!("{url}/sdcpp/v1/img_gen"))
        .json(&body)
        .send()
        .map_err(|e| format!("the renderer did not accept the request: {e}"))?
        .json()
        .map_err(|e| format!("the renderer's reply was not json: {e}"))?;
    let poll = job
        .get("poll_url")
        .and_then(|v| v.as_str())
        .ok_or("the renderer accepted the job but named no poll_url")?
        .to_string();

    let deadline = std::time::Instant::now() + std::time::Duration::from_secs(120);
    loop {
        if std::time::Instant::now() > deadline {
            return Err("the renderer never finished the job".into());
        }
        let st: serde_json::Value = client
            .get(format!("{url}{poll}"))
            .send()
            .map_err(|e| format!("cannot poll the renderer: {e}"))?
            .json()
            .map_err(|e| format!("the renderer's status was not json: {e}"))?;
        match st.get("status").and_then(|v| v.as_str()).unwrap_or("") {
            "completed" => {
                let b64 = st
                    .pointer("/result/images/0/b64_json")
                    .and_then(|v| v.as_str())
                    .ok_or("the renderer completed but returned no image")?;
                return base64::engine::general_purpose::STANDARD
                    .decode(b64)
                    .map_err(|e| format!("the renderer's image did not decode: {e}"));
            }
            "failed" => {
                let why = st.get("error").and_then(|v| v.as_str()).unwrap_or("no reason given");
                return Err(format!("the renderer failed: {why}"));
            }
            _ => std::thread::sleep(std::time::Duration::from_millis(20)),
        }
    }
}

/// Ask the scene model what is happening. Best-effort: a failure means the transcript is drawn
/// directly, which is a faster path rather than a broken one.
fn infer_scene(url: &str, model: &str, transcript: &str, at_unix_ms: i64) -> Option<Scene> {
    let prompt = format!(
        "You infer the visual scene behind overheard speech. Reply with ONE short visual sentence: \
         who is present, where, what they are doing, the light/weather. No preamble, no quotes.\
         \n\nSPEECH: {transcript}"
    );
    let client = reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(30))
        .build()
        .ok()?;
    let v: serde_json::Value = client
        .post(format!("{url}/api/generate"))
        .json(&serde_json::json!({
            "model": model, "prompt": prompt, "stream": false, "think": false,
            "options": { "num_predict": 40, "temperature": 0.7 }
        }))
        .send()
        .ok()?
        .json()
        .ok()?;
    let text = v.get("response")?.as_str()?.trim().replace('\n', " ");
    if text.is_empty() {
        return None;
    }
    Some(Scene { text, at_unix_ms, tier: None })
}

/// Draw one thought and append it to the feed. Returns the entry, or why it was skipped.
pub fn draw(
    dir: &Path,
    transcript: &str,
    cue: &Cue,
    previous: Option<&str>,
    at_unix_ms: i64,
    n: u64,
) -> Result<Option<Entry>, String> {
    match worth_imagining(transcript, previous) {
        Ok(()) => {}
        Err(Skip::Blank) | Err(Skip::Hallucination) | Err(Skip::Unchanged) => return Ok(None),
    }
    let url = sd_url();
    let scene = llm_url().and_then(|u| infer_scene(&u, &llm_model(), transcript, at_unix_ms));
    // The scene stage may name a tier; when it does not, the ear's own cues decide.
    let tier = scene.as_ref().and_then(|s| s.tier).unwrap_or_else(|| crate::choose_tier(cue));
    let prompt = scene.as_ref().map(|s| s.text.clone()).unwrap_or_else(|| transcript.to_string());

    let started = std::time::Instant::now();
    let png = match render_png(&url, &prompt, tier, seed_for(&cue_key(cue))) {
        Ok(b) => b,
        Err(e) => {
            let _ = store::set_fault(dir, &e);
            return Err(e);
        }
    };
    let render_ms = started.elapsed().as_millis().min(u128::from(u32::MAX)) as u32;

    let id = mint_id(at_unix_ms, n);
    std::fs::create_dir_all(dir).map_err(|e| format!("cannot create the feed: {e}"))?;
    std::fs::write(store::image_path(dir, &id), &png)
        .map_err(|e| format!("cannot write the image: {e}"))?;
    let entry = Entry {
        id: id.clone(),
        at_unix_ms,
        transcript: transcript.to_string(),
        scene: scene.map(|s| s.text),
        image: format!("{id}.png"),
        tier,
        render_ms,
    };
    store::append(dir, &entry)?;
    let _ = store::clear_fault(dir);
    let _ = store::sweep(dir, at_unix_ms, &Budget::default());
    Ok(Some(entry))
}

/// The key a seed is derived from. Today the language tag plus liveness — a coarse stand-in for the
/// speaker. When the ear's voiceprints become stable across recordings this becomes the voiceprint,
/// and each person gets their own persistent visual world.
fn cue_key(cue: &Cue) -> String {
    format!("live={}", cue.live)
}

/// The ear's transcript log.
pub fn ear_transcripts(ear_root: &Path) -> PathBuf {
    ear_root.join("transcripts.jsonl")
}

/// One transcript row, read leniently: the ear owns this shape and this is a READER, so an unknown
/// field must never stop a thought being drawn.
pub struct Heard {
    pub at_unix_ms: i64,
    pub seconds: f32,
    pub live: bool,
    pub text: String,
}

/// When the ear was heard, from whichever spelling of the key this row carries.
///
/// THE TWO SPELLINGS ARE REAL AND THIS COST A LIVE FEATURE. The on-disk `transcripts.jsonl` is
/// serde's own output, so the field is `started_unix_ms`; `bsc ear transcripts --json` PRINTS
/// `startedUnixMs`. Reading only the printed spelling meant the lookup always missed on the file
/// this actually reads — and the miss was absorbed by an `unwrap_or(0)`, so every thought was
/// stamped at the epoch, fell outside the retention window the moment it was written, and the
/// widget could never show anything a live producer drew.
///
/// Both are accepted because both are real shapes a caller may hand us. What is NOT accepted is a
/// row with neither: that returns `None` so the row is skipped, because a missing timestamp must
/// read as MISSING. A default here cannot be right — every candidate value is a lie about when
/// something was said, and 0 is the lie that looks most like a number.
fn heard_at(v: &serde_json::Value) -> Option<i64> {
    v.get("started_unix_ms")
        .or_else(|| v.get("startedUnixMs"))
        .and_then(|x| x.as_i64())
}

/// Parse the ear's transcript log. Unparseable lines are skipped, as in [`store::parse_entries`]
/// and for the same reason: the writer is live.
pub fn parse_heard(text: &str) -> Vec<Heard> {
    text.lines()
        .filter_map(|l| serde_json::from_str::<serde_json::Value>(l).ok())
        .filter_map(|v| {
            // An ABSENT text field and an EMPTY one both mean no words were heard, so both drop
            // here rather than one dropping and the other travelling on to be refused later.
            let text = v.get("text")?.as_str()?.trim().to_string();
            if text.is_empty() {
                return None;
            }
            Some(Heard {
                at_unix_ms: heard_at(&v)?,
                seconds: v.get("seconds").and_then(|x| x.as_f64()).unwrap_or(0.0) as f32,
                // The ear records live-vs-playback; absent means it could not tell, and an unknown
                // voice is treated as live rather than silently demoted to the cheapest tier.
                live: v.get("live").and_then(|x| x.as_bool()).unwrap_or(true),
                text,
            })
        })
        .collect()
}

/// Does a renderer actually answer? Probed, never assumed from configuration.
pub fn renderer_answers(url: &str) -> bool {
    reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_millis(1500))
        .build()
        .ok()
        .and_then(|c| c.get(format!("{url}/sdcpp/v1/capabilities")).send().ok())
        .map(|r| r.status().is_success())
        .unwrap_or(false)
}

#[derive(Default)]
struct Args {
    json: bool,
    pretty: bool,
    once: bool,
    dir: Option<String>,
    ear: Option<String>,
    positional: Vec<String>,
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let (mut a, positional) = args::walk(raw, Args::default(), |flag, a: &mut Args, rest| {
        match flag {
            "--json" => a.json = true,
            "--pretty" => a.pretty = true,
            "--once" => a.once = true,
            "--dir" => a.dir = Some(rest.value("--dir needs a path")?),
            "--ear" => a.ear = Some(rest.value("--ear needs a path")?),
            _ => return Ok(false),
        }
        Ok(true)
    })?;
    a.positional = positional;
    Ok(a)
}

fn base() -> Result<PathBuf, String> {
    bsc_util::bsc_base_dir().ok_or_else(|| "no home directory, so ~/.base-studio-code could not be resolved".to_string())
}

fn feed_of(a: &Args) -> Result<PathBuf, String> {
    Ok(match &a.dir {
        Some(d) => PathBuf::from(d),
        None => store::feed_dir(&base()?),
    })
}

fn ear_of(a: &Args) -> Result<PathBuf, String> {
    Ok(match &a.ear {
        Some(d) => PathBuf::from(d),
        None => base()?.join("ear"),
    })
}

fn cmd_once(a: &Args) -> Result<(), String> {
    let text = a.positional.get(1..).map(|r| r.join(" ")).unwrap_or_default();
    if text.trim().is_empty() {
        return Err("bsc imagine once needs the text to draw".into());
    }
    let dir = feed_of(a)?;
    let now = bsc_util::now_ms();
    let previous = match store::read(&dir, now, &Budget::default()) {
        crate::FeedState::Ready { entries } => crate::newest(&entries).map(|e| e.transcript.clone()),
        // Enumerated, not wildcarded: a fifth feed state must break here and be thought about.
        crate::FeedState::Absent | crate::FeedState::Empty | crate::FeedState::Failing { .. } => None,
    };
    let cue = Cue { arousal_z: 0.0, seconds: 10.0, live: true };
    match draw(&dir, &text, &cue, previous.as_deref(), now, now as u64 % 1000)? {
        Some(e) => {
            bsc_cli_util::emit(a.pretty, a.json, &e, || {
                let mut out = format!("drew {} · {:?} · {}ms\n", e.id, e.tier, e.render_ms);
                if let Some(sc) = &e.scene {
                    out.push_str(&format!("  scene  {sc}\n"));
                }
                out.push_str(&format!("  heard  {}", e.transcript));
                out
            });
            Ok(())
        }
        None => {
            bsc_cli_util::emit(a.pretty, a.json, &serde_json::json!({ "drawn": false }), || {
                "nothing drawn — that text is blank, an ASR hallucination, or already the newest thought".to_string()
            });
            Ok(())
        }
    }
}

fn cmd_status(a: &Args) -> Result<(), String> {
    let dir = feed_of(a)?;
    let now = bsc_util::now_ms();
    let state = store::read(&dir, now, &Budget::default());
    let url = sd_url();
    let answers = renderer_answers(&url);
    let v = serde_json::json!({
        "feed": state, "dir": dir.display().to_string(),
        "renderer": { "url": url, "answers": answers },
        "scene": { "url": llm_url(), "model": llm_model() },
    });
    bsc_cli_util::emit(a.pretty, a.json, &v, || {
        let mut out = format!("feed        {}\n", dir.display());
        out.push_str(&match &state {
            crate::FeedState::Absent => "state       ABSENT — nothing has ever drawn here\n".to_string(),
            crate::FeedState::Empty => "state       empty — a producer has run and the room was quiet\n".to_string(),
            crate::FeedState::Ready { entries } => format!("state       {} thought(s) held\n", entries.len()),
            crate::FeedState::Failing { reason } => format!("state       FAILING — {reason}\n"),
        });
        // The distinction this probe exists for: configured is not the same as answering.
        out.push_str(&format!("renderer    {url} — {}\n", if answers { "answers" } else { "NO ANSWER" }));
        out.push_str(&match llm_url() {
            Some(u) => format!("scene       {u} ({})", llm_model()),
            None => "scene       none — thoughts are drawn straight from what was heard".to_string(),
        });
        out
    });
    Ok(())
}

fn cmd_sweep(a: &Args) -> Result<(), String> {
    let dir = feed_of(a)?;
    let n = store::sweep(&dir, bsc_util::now_ms(), &Budget::default())?;
    bsc_cli_util::emit(a.pretty, a.json, &serde_json::json!({ "evicted": n }), || {
        format!("evicted {n} thought(s) and their images")
    });
    Ok(())
}

fn cmd_watch(a: &Args) -> Result<(), String> {
    let dir = feed_of(a)?;
    let log = ear_transcripts(&ear_of(a)?);
    let url = sd_url();
    if !renderer_answers(&url) {
        // Recorded on the FEED, not merely printed, so the widget can say nobody is drawing
        // rather than showing a room that looks quiet.
        let msg = format!("no renderer answers at {url}");
        let _ = store::set_fault(&dir, &msg);
        return Err(msg);
    }
    let _ = store::clear_fault(&dir);
    // Everything already in the log is history, not news — `watch` draws what arrives NEXT unless
    // --once was asked for, which is what a test wants.
    let mut seen = if a.once { 0 } else { count_lines(&log) };
    let mut n: u64 = 0;
    let mut previous: Option<String> = None;
    loop {
        let text = std::fs::read_to_string(&log).unwrap_or_default();
        let heard = parse_heard(&text);
        for h in heard.iter().skip(seen) {
            let cue = Cue { arousal_z: 0.0, seconds: h.seconds, live: h.live };
            match draw(&dir, &h.text, &cue, previous.as_deref(), h.at_unix_ms, n) {
                Ok(Some(e)) => {
                    println!("{} · {:?} · {}ms · {}", e.id, e.tier, e.render_ms, e.transcript);
                    previous = Some(e.transcript.clone());
                    n += 1;
                }
                Ok(None) => {}
                // A failed draw must not stop the watch: the ear keeps hearing, and the fault is
                // already recorded on the feed for the widget to show.
                Err(e) => eprintln!("could not draw: {e}"),
            }
        }
        seen = heard.len();
        if a.once {
            return Ok(());
        }
        std::thread::sleep(std::time::Duration::from_millis(WATCH_POLL_MS));
    }
}

fn count_lines(p: &Path) -> usize {
    std::fs::read_to_string(p).map(|s| parse_heard(&s).len()).unwrap_or(0)
}

pub fn run(argv: Vec<String>, prog: &str) -> Result<(), String> {
    let a = parse_args(argv)?;
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &a.positional) {
        return Ok(());
    }
    match a.positional.first().map(String::as_str) {
        Some("once") => cmd_once(&a),
        Some("watch") => cmd_watch(&a),
        Some("status") => cmd_status(&a),
        Some("sweep") => cmd_sweep(&a),
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other.unwrap_or(""))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_minted_id_is_accepted_by_the_apps_filename_validator() {
        // The app refuses anything but [A-Za-z0-9_-]; a producer that minted an id outside that
        // set would write images the widget could never fetch.
        for (at, n) in [(1_788_617_448_002_i64, 0u64), (0, 999)] {
            let id = mint_id(at, n);
            assert!(
                id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_'),
                "{id} is not a safe filename stem"
            );
            assert!(!id.is_empty() && id.len() <= 128);
        }
    }

    #[test]
    fn the_seed_is_stable_for_a_key_and_differs_between_keys() {
        // Stability is the whole mechanism: a fixed seed across an evolving prompt is what holds
        // consecutive images in one world (SSIM 0.957 vs 0.450 measured).
        assert_eq!(seed_for("live=true"), seed_for("live=true"));
        assert_ne!(seed_for("live=true"), seed_for("live=false"));
        // Never negative when handed to a renderer expecting an unsigned seed.
        assert!(seed_for("anything") < 0x8000_0000);
    }

    // VERBATIM lines from a real ~/.base-studio-code/ear/transcripts.jsonl. Taken from the file
    // rather than hand-written, because the bug this fixture exists to catch was an ASSUMPTION
    // about the field name — and a fixture invented alongside the parser tests the parser against
    // the author's belief instead of against the ear.
    const REAL_LOG: &str = concat!(
        r#"{"segment":"seg-1788717359976-022.wav","started_unix_ms":1788717359976,"seconds":3.86,"language":"en","text":"ha ha ha ha ha","live":null}"#, "\n",
        r#"{"segment":"seg-1788717504142-052.wav","started_unix_ms":1788717504142,"seconds":1.66,"language":"en","text":"*sigh*","live":null}"#, "\n",
    );

    #[test]
    fn the_timestamp_is_read_from_a_real_transcript_line() {
        // THE REGRESSION. Reading only `startedUnixMs` made this 0 on every real row, which put
        // every drawn thought ~57 years outside the retention window — so a populated feed read
        // `empty` and the widget could never show a live producer's work.
        let rows = parse_heard(REAL_LOG);
        assert_eq!(rows.len(), 2, "both real lines must parse");
        assert_eq!(rows[0].at_unix_ms, 1_788_717_359_976);
        assert_eq!(rows[1].at_unix_ms, 1_788_717_504_142);
        assert_ne!(rows[0].at_unix_ms, 0, "a real row must never land at the epoch");
        assert_eq!(rows[0].text, "ha ha ha ha ha");
        assert!((rows[0].seconds - 3.86).abs() < 1e-6);
        // `live` is null on disk — the ear could not tell. An unknown voice stays live rather than
        // being silently demoted to the cheapest tier.
        assert!(rows[0].live);
    }

    #[test]
    fn a_drawn_thought_from_a_real_line_lands_inside_the_retention_window() {
        // The consequence, asserted end to end against the bound rather than against the parser.
        let h = &parse_heard(REAL_LOG)[0];
        let e = Entry {
            id: mint_id(h.at_unix_ms, 0),
            at_unix_ms: h.at_unix_ms,
            transcript: h.text.clone(),
            scene: None,
            image: "x.png".into(),
            tier: Tier::Reflex,
            render_ms: 205,
        };
        // "now" is a LITERAL moment just after the fixture's real timestamp — deliberately NOT
        // derived from the parsed value. Deriving it made this test vacuous: with the old bug the
        // parse returned 0, `now` moved to 0 with it, and the entry looked fresh. A reference the
        // bug can move is not a reference.
        let now = 1_788_717_359_976_i64 + 1_000;
        let kept = crate::retain(&[e], now, &Budget::default());
        assert_eq!(kept.len(), 1, "a freshly heard thought must survive the bound");
    }

    #[test]
    fn the_cli_json_spelling_is_accepted_too() {
        // `bsc ear transcripts --json` prints camelCase. Both are real shapes a caller may hand us.
        let rows = parse_heard(r#"{"startedUnixMs":1788717359976,"seconds":2.0,"text":"printed shape"}"#);
        assert_eq!(rows.len(), 1);
        assert_eq!(rows[0].at_unix_ms, 1_788_717_359_976);
    }

    #[test]
    fn a_row_with_no_timestamp_is_skipped_rather_than_stamped_zero() {
        // A default cannot be right here: every candidate is a lie about when something was said,
        // and 0 is the lie that looks most like a number.
        assert!(parse_heard(r#"{"seconds":1.0,"text":"no timestamp anywhere"}"#).is_empty());
        assert!(parse_heard(r#"{"started_unix_ms":null,"seconds":1.0,"text":"explicit null"}"#).is_empty());
        assert!(parse_heard(r#"{"started_unix_ms":"not a number","text":"wrong type"}"#).is_empty());
    }

    #[test]
    fn a_bad_line_is_skipped_without_stopping_the_read() {
        let mixed = format!("{REAL_LOG}not json at all\n{{\"started_unix_ms\":5,\"text\":\"\"}}\n");
        let rows = parse_heard(&mixed);
        assert_eq!(rows.len(), 2, "the two real rows survive a bad line and an empty-text row");
    }

    #[test]
    fn the_default_renderer_is_local_only() {
        // Nothing about this system may reach a third party on a default path.
        assert!(DEFAULT_SD_URL.starts_with("http://127.0.0.1"), "the default renderer must be loopback");
    }

    #[test]
    fn every_command_is_documented_and_reachable() {
        let names: Vec<&str> = COMMANDS.iter().map(|c| c.name).collect();
        assert_eq!(names, ["once", "watch", "status", "sweep"]);
        for c in COMMANDS {
            assert!(!c.summary.is_empty(), "{} has no summary", c.name);
            assert!(c.usage.contains(c.name), "{}'s usage does not name it", c.name);
        }
    }
